/**
 * APAAR-SDMS API Schema & Types
 * Source contracts: agents.md §2, §5, §6, §7
 * 
 * Once contracts/openapi.yaml is generated by Team B,
 * run `npm run codegen` to generate openapi-typescript bindings.
 */

export type UserRole =
  | 'AICTE_ADMIN'
  | 'AICTE_ANALYST'
  | 'INSTITUTION_ADMIN'
  | 'INSTITUTION_STAFF'
  | 'VERIFIER'
  | 'STUDENT';

export interface UserProfile {
  id: string;
  email: string;
  full_name: string;
  role: UserRole;
  institution_aicte_id?: string;
  institution_name?: string;
  apaar_id?: string; // For student role
}

export interface AuthResponse {
  access_token: string;
  token_type: string;
  expires_in: number;
  user: UserProfile;
}

export type CourseLevel = 'DIPLOMA' | 'UG' | 'PG' | 'PGDM' | 'PHD';
export type Gender = 'M' | 'F' | 'T';
export type SocialCategory = 'GEN' | 'EWS' | 'OBC-NCL' | 'SC' | 'ST';
export type AdmissionType = 'REGULAR' | 'LATERAL' | 'TRANSFER';
export type SeatType = 'REGULAR' | 'SUPERNUMERARY';
export type SupernumeraryScheme =
  | 'TFW'
  | 'PMSSS'
  | 'JK'
  | 'NE'
  | 'FN_OCI_NRI'
  | 'OTHER'
  | null;
export type Quota = 'NONE' | 'NRI' | 'OCI' | 'FN' | 'PIO' | 'CIWG';
export type EnrolmentStatus = 'ACTIVE' | 'WITHDRAWN' | 'DEFERRED' | 'COMPLETED';
export type ConsentStatus = 'GRANTED' | 'REFUSED' | 'WITHDRAWN';

export interface StudentRecord {
  apaar_id: string; // 12-digit string or masked "1234****9012"
  institution_aicte_id: string;
  institution_student_id: string;
  full_name: string;
  name_norm?: string;
  dob: string; // YYYY-MM-DD
  gender: Gender;
  category: SocialCategory;
  pwd: boolean;
  program_code: string;
  course_level: CourseLevel;
  academic_year: string;
  admission_date: string;
  admission_type: AdmissionType;
  seat_type: SeatType;
  supernumerary_scheme?: SupernumeraryScheme;
  quota: Quota;
  nationality: string; // ISO-3166 alpha-2
  nri_status: boolean;
  oci_status: boolean;
  fn_status: boolean;
  enrolment_status: EnrolmentStatus;
  consent_status: ConsentStatus;
  consent_date?: string;
  guardian_consent?: boolean;
  email?: string;
  mobile?: string;
}

export interface ProgramIntake {
  institution_aicte_id: string;
  program_code: string;
  program_name: string;
  academic_year: string;
  approved_intake: number;
  regular_enrolled?: number;
  supernumerary_enrolled?: number;
  supernumerary_allowed: Record<string, number>;
  approval_letter_ref: string;
}

export type RuleSeverity = 'ERROR' | 'WARN';

export interface Issue {
  row: number;
  field: string;
  rule_id: string;
  severity: RuleSeverity;
  message: string;
  value_masked: string;
}

export interface IntakeSummaryItem {
  program_code: string;
  approved: number;
  enrolled: number;
  supernumerary: number;
  excess: number;
}

export interface DuplicateCluster {
  cluster_id: string;
  apaar_ids: string[];
  students?: Partial<StudentRecord>[];
  score: number;
  scope: 'INTRA' | 'CROSS_INSTITUTION';
  institution_aicte_ids?: string[];
  status?: 'PENDING' | 'RESOLVED' | 'DISMISSED';
  match_reasons?: string[];
}

export interface AnomalyItem {
  id: string;
  institution_aicte_id: string;
  institution_name?: string;
  metric: string;
  value: number;
  baseline: number;
  z: number;
  reason: string;
  timestamp: string;
  status?: 'NEW' | 'ACKNOWLEDGED' | 'ESCALATED';
}

export interface BatchReport {
  batch_id: string;
  institution_aicte_id: string;
  institution_name?: string;
  academic_year: string;
  created_at: string;
  status: 'PENDING' | 'PROCESSING' | 'COMPLETED' | 'FAILED';
  rows_total: number;
  rows_valid: number;
  rows_warning: number;
  rows_error: number;
  quality_score: number;
  metrics: {
    completeness: Record<string, number>;
    uniqueness: Record<string, number>;
  };
  issues: Issue[];
  intake_summary: IntakeSummaryItem[];
  duplicate_clusters: DuplicateCluster[];
  anomalies: AnomalyItem[];
}

export interface BatchListItem {
  batch_id: string;
  institution_aicte_id: string;
  institution_name: string;
  filename: string;
  academic_year: string;
  uploaded_at: string;
  status: 'PROCESSING' | 'COMPLETED' | 'FAILED';
  rows_total: number;
  rows_valid: number;
  rows_error: number;
  quality_score: number;
}

export interface ConsentRecord {
  apaar_id: string;
  purpose: 'REPOSITORY' | 'VERIFICATION_SHARE';
  status: ConsentStatus;
  granted_at?: string;
  withdrawn_at?: string;
  disclosed_fields: string[];
  guardian_consent_verified?: boolean;
}

export interface VerificationRequest {
  credential_jwt?: string;
  qr_payload?: string;
  disclosed_claims?: Record<string, unknown>;
}

export interface VerificationResult {
  verified: boolean;
  reason?: string;
  issuer_did: string;
  issuer_name: string;
  issuance_timestamp: string;
  checks: {
    signature_valid: boolean;
    issuer_trusted: boolean;
    not_revoked: boolean;
    expired: boolean;
  };
  disclosed_fields: {
    apaar_id_masked: string;
    student_name: string;
    institution_name: string;
    program_code: string;
    academic_year: string;
    course_level: string;
    enrolment_status: string;
    [key: string]: unknown;
  };
}

export interface AuditLogEntry {
  id: string;
  timestamp: string;
  actor_id: string;
  actor_role: UserRole;
  action: string;
  resource_type: string;
  resource_id: string;
  details_masked: Record<string, unknown>;
  prev_hash: string;
  hash: string;
}

export interface AuditChainStatus {
  chain_valid: boolean;
  total_blocks: number;
  latest_hash: string;
  genesis_hash: string;
  broken_link_index: number | null;
  last_verified_at: string;
}
